-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.normalize_invite_email(raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select lower(regexp_replace(coalesce(raw, ''),
                              '[[:space:]\u00a0\u2007\u202f\u200b\u200c\u200d\u2060\ufeff]+', '', 'g'));
$function$;

grant execute on function public.normalize_invite_email(raw text) to service_role;
